issues.suggestion:
Use DOM API methods (createElement, textContent) instead of string concatenation for HTML generation, or use a sanitization library like DOMPurify. Example:
```javascript
export function highlight(title, query) {
  const div = document.createElement('div');
  div.textContent = title; // Auto-escapes
  let html = div.innerHTML;
  const terms = query.split(' ');
  terms.forEach(term => {
    const escapedTerm = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(${escapedTerm})`, 'gi');
    html = html.replace(regex, '<mark>$1</mark>');
  });
  return html;
}
```

